from pathlib import Path
import json,re
R=Path(__file__).resolve().parent.parent
M=json.loads((R/'.validation/modelo.json').read_text(encoding='utf8'))
T=M['tables']; D=M['descriptions']; refs=M['refs']; U=M['uniques']; C=M['checks']
views=[]
def V(name,path,observed,tables,rule,status='Inspeccionada en la aplicación'):
    views.append(dict(name=name,path=path,observed=observed,tables=tables.split(),rule=rule,status=status))
V('Bienvenido','Acceso > Selección de perfil','Selector Administrador / Chofer y acceso de demostración sin contraseña. El selector de chofer permite elegir personas con y sin asignaciones.', 'personas roles usuarios archivos sesiones_usuario', 'Una persona puede actuar como proveedor y como conductor sin duplicar su identidad. Un usuario tiene un rol en este alcance. La sesión persistente es una propuesta técnica: el retorno al login al recargar no se corrige únicamente creando tablas. El backend debe emitir/verificar una cookie o token con vencimiento, y el frontend restaurar sesión antes de cargar el perfil. Nunca guardar el token en claro ni usar los nombres del demo como autenticación real.')
V('Módulos del sistema','Administrador > Inicio','Ocho tarjetas: Gestión Comercial; Gestión de Campaña; Gestión de Proveedores; Gestión de Transporte; Cosecha y Control de Calidad; Logística y Despacho; Facturación y cobros; Liquidación de Compra.','', 'No representa una tabla de negocio. Es navegación y permisos sobre entidades compartidas. No se observó un módulo de sueldos. Los nombres de breadcrumb de este informe son rutas lógicas propuestas; la navegación inspeccionada mantiene la URL raíz, no URLs técnicas distintas.')
V('Gestión Comercial — Clientes','Administrador > Gestión Comercial > Clientes','Empresa, contacto, teléfono, correo corporativo, RUC, tipo Exportador/Industria; acciones nuevo, ver, editar y vincular a campaña.', 'clientes destinos_cliente', 'El cliente es una identidad comercial persistente y sus plantas/destinos son registros hijos. Contacto no equivale a usuario. RUC único, conservado como texto. Los destinos deben pertenecer al cliente del contrato; el SQL valida esa coincidencia.')
V('Detalle de cliente','Administrador > Gestión Comercial > Clientes > Detalle','Ficha de SUTRIMEX con ubicación y fecha de registro; participaciones por campaña con cantidades, kilos acordados, número de contratos y ficha técnica.','clientes requerimientos_comerciales contratos_venta', 'La ficha agrega información desde requerimientos y contratos. No crear tablas detalle_cliente ni copia de campañas. Cantidad registrada, kilos acordados y kilos entregados son métricas diferentes.')
V('Contratos — Participaciones comerciales','Administrador > Gestión Comercial > Contratos','Listado por cliente y campaña, filtros, cantidad en kg, kilos acordados, fecha de registro y varios contratos por participación. El formulario Editar participación incluye ficha técnica, varias variedades, destino solicitado y ventana desde/hasta.', 'requerimientos_comerciales requerimiento_variedades', 'Separar necesidad comercial y contrato firmado. Una campaña y un cliente pueden tener varios requerimientos: los datos compartidos muestran varias participaciones de Batimix en Mango 2026, así que no imponer UNIQUE(cliente,campaña) sin depuración. Requerimiento→contratos es 1:N. El destino solicitado puede ser una ciudad/país y no necesariamente la planta de llegada.')
V('Consulta cliente–campaña','Administrador > Gestión Comercial > Contratos > Participación','Consulta SUTRIMEX — Mango 2026 con ficha técnica, cuatro contratos, variedades requeridas, destino Rotterdam, ventana de entrega, resumen de entregas y entregas logísticas relacionadas.','requerimientos_comerciales requerimiento_variedades contratos_venta entregas_programadas', 'Reutiliza la participación y agrega contratos y entregas por sus claves. La suma programada no debe confundirse con lo efectivamente cargado o recibido. Los archivos se referencian por identificador de almacenamiento.')
V('Contratos del cliente en campaña','Administrador > Gestión Comercial > Contratos > Participación > Contratos','Varios contratos con fecha, kilos, precio/kg, moneda, precio total, archivo y número de entregas. En una misma participación se observaron contratos USD y PEN.','contratos_venta', 'El contrato pertenece a un requerimiento; su cliente y campaña se obtienen desde este. Precio total=kg acordados×precio/kg. No sumar importes de monedas distintas. Se adopta un precio por contrato, como la UI; se retira precios_venta del modelo compacto para evitar dos fuentes editables. Si luego se confirma precio diferente por variedad, sustituir el precio de cabecera por líneas completas, sin duplicarlo.')
V('Entregas programadas','Administrador > Gestión Comercial > Contratos > Contrato > Entregas','Fecha programada, kilos, destino, preparación y acciones registrar, ver, editar programación o quitar. Edición deshabilitada con carga registrada.', 'entregas_programadas entrega_variedades', 'Contrato 1:N entregas. Los kilos de todas las entregas no pueden superar el contrato. La distribución por variedad alimenta el programa semanal y debe sumar exactamente la cabecera; insertar cabecera y líneas en una misma transacción porque el SQL comprueba la suma al confirmar. No crear una tabla por pestaña de estado.')
V('Gestión de Campaña','Administrador > Gestión de Campaña > Listado','Pestañas Planificado, En Proceso y Finalizado; filtros por fruta, periodo y fechas; cantidad comercial derivada; campañas Mango, Palta, Arándano y demo.', 'frutas variedades campanias campania_variedades', 'Una fruta por campaña y varias variedades de esa fruta. Un responsable es un usuario, no un nombre libre nuevo por campaña. El inicio automático depende de fecha; el cierre es manual. No almacenar como atributos los contadores y brechas del tablero. El SQL no ejecuta un programador para pasar automáticamente a EN_PROCESO; corresponde al servicio o a un job.')
V('Datos generales y resumen de campaña','Administrador > Gestión de Campaña > Campaña > Detalle','Mango 2026: responsable, periodo, frutas/variedades, lineamientos, observaciones, oferta estimada, validada, kilos certificados, comprometidos y brechas; advertencias de recepción incompleta.','campanias participaciones_proveedor certificaciones contratos_venta cosechas cargas', 'Son consultas sobre varias entidades. Distinguir sumas por requerimiento, contrato, proveedor y certificado; agregar cada conjunto por separado antes de combinarlos para evitar multiplicar kilos por un JOIN 1:N. La advertencia de cobertura duplicada no acredita producción nueva.')
V('Proveedores de campaña','Administrador > Gestión de Campaña > Planificado > Campaña > Proveedores','Proveedores vinculados con rol Productor/Acopiador, cantidad estimada, estado de evaluación y si hubo entrevista. Detalle Roberto Palacios muestra varias fincas, varias variedades y fruta orgánica.','participaciones_proveedor participacion_variedades fincas_campania', 'La participación es la identidad del proveedor dentro de la campaña. No usar acuerdos_compra como sustituto: todavía puede no existir precio, finca entrevistada o compra. El SQL asegura que la finca pertenece al proveedor de la participación. Un proveedor puede cambiar su rol comercial entre campañas sin alterar su identidad general.')
V('Entrevista','Administrador > Gestión de Campaña > Planificado > Proveedores > Participación > Entrevista','Fincas entrevistadas con fecha y hora automáticas, código FYV, hectáreas y datos agronómicos. El detalle muestra densidad, distanciamiento, frecuencia de riego, aplicación y aplicaciones al año.','entrevistas fincas_campania acuerdos_compra', 'Cada entrevista corresponde a una finca vinculada y conserva su fecha; se permiten nuevas revisiones sin sobrescribir la finca general. Las condiciones de compra son una entidad propuesta reutilizada para precios por origen y vigencia; no se observó un editor independiente de acuerdos_compra durante el recorrido. El precio aplicado se captura al liquidar y no se recalcula desde un precio vigente que haya cambiado.')
V('Exámenes','Administrador > Gestión de Campaña > Planificado > Proveedores > Participación > Exámenes','Exámenes Roberto Palacios en Palta 2027: fruta, análisis, código de muestra, origen, fecha de toma, fecha de envío, estado, resultado, documento y observación.','examenes', 'Un examen es una fila por muestra/análisis de la participación; su finca puede ser opcional cuando el dato no está disponible. Resultado debe poder quedar pendiente. Se corrige el DBML que exigía resultado y acuerdo de compra desde el inicio. No confundir estos exámenes de evaluación con el análisis operativo de una cosecha.')
V('Certificaciones','Administrador > Gestión de Campaña > Planificado > Campaña > Certificaciones','Certificado Palta 2027: nombre, documento, vigencia, tipo, organismo, productores cubiertos, kilos iniciales, ampliaciones, total y pago. La pantalla declara un certificado por campaña.','normas certificaciones certificacion_proveedor', 'Se separa el certificado propio del proveedor. Un certificado de campaña cubre varias participaciones de la misma campaña; se capturan los kg iniciales por productor. El total inicial se obtiene de esas filas, y las ampliaciones se suman aparte. El SQL aplica unicidad de campaña según esta pantalla; revisar esa regla si una futura campaña admite varios certificados.')
V('Ampliación de certificación','Administrador > Gestión de Campaña > Certificaciones > Ampliación','Formulario con kilos adicionales, fecha, referencia/evidencia y total de kilos iniciales y ampliaciones actuales.','ampliaciones_certificacion', 'Cada ampliación es un evento con kilos positivos; no sustituye ni modifica los kilos iniciales. En el formulario observado la evidencia es texto de referencia, no un archivo obligatorio. Se preserva el evento sin edición destructiva.')
V('Pago de certificación','Administrador > Gestión de Campaña > Certificaciones > Pagos','Formulario con costo USD 2,400, pagado, monto, fecha, referencia y archivo de evidencia.','pagos_certificacion', 'Una certificación admite pagos parciales. El monto se interpreta en su moneda; no crear un segundo costo por pago. El SQL bloquea el sobrepago y conserva los movimientos. Después de pagos o ampliaciones, la cabecera queda protegida.')
V('Transportistas por campaña','Administrador > Gestión de Campaña > En Proceso > Campaña > Transportistas','Listado de transportistas vinculados con documento, ubicación, teléfono, correo, fecha de vinculación y acuerdo de pago. Incluye empresa e independiente.','acuerdos_transporte', 'Una vinculación de transporte por empresa/campaña; el acuerdo guarda modalidad y flete autorizado. Los adelantos son desembolsos separados. En el SQL, el acuerdo se registra completo al vincular: si se necesita guardar una vinculación sin acuerdo, separar una cabecera de vinculación o permitir un borrador antes de exigir montos.')
V('Entregas de la campaña','Administrador > Gestión de Campaña > En Proceso > Campaña > Entregas','Listado de entregas comerciales con estados Por completar, Lista para carga y Con carga registrada; acciones completar o consultar.','entregas_programadas coordinaciones_entrega', 'Una entrega programada puede existir sin coordinación, y una coordinación sin carga real. Estas tres etapas no deben forzar kilos ficticios ni una cosecha para permitir la asignación del chofer.')
V('Completar coordinación de entrega','Administrador > Gestión de Campaña > En Proceso > Entregas > Coordinación','Formulario inspeccionado: contrato, transportista vinculado, varios proveedores y varias fincas de cada uno, camión, chofer, inicio/fin del viaje, origen, condiciones y observaciones.','coordinaciones_entrega origenes_entrega', 'El camión y el chofer deben pertenecer al transportista del acuerdo y este a la campaña. Los orígenes son fincas de participaciones de esa campaña. Exportación admite origen orgánico según el prototipo. Una fila por finca evita guardar una cadena de nombres como relación. La descripción de origen sí puede mantenerse como texto informativo.')
V('Programa semanal de entregas','Administrador > Gestión de Campaña > Campaña > Programa semanal de entregas','Selector de semana ISO, variedad, días lunes–domingo, cliente/contrato, placa, kilos y total. La pantalla dice que los kg se cuentan una sola vez y la placa se completa después.','entregas_programadas entrega_variedades coordinaciones_entrega', 'Es una proyección de la programación, no una tabla calendario ni un registro de carga. La vista SQL v_programa_semanal usa año ISO y semana ISO para no mezclar semanas de distintos años; admite vehículo todavía sin asignar.')
V('Gestión de proveedores','Administrador > Gestión de Proveedores > Listado','Nombre completo, documento, zona, frutas asociadas, variedades y estado de sanidad.','proveedores personas_proveedor proveedor_frutas proveedor_variedades', 'Separar persona, proveedor y participación. Las personas vinculadas se reutilizan para liquidaciones y control anual; no crean un proveedor nuevo ni transfieren compras antiguas. Las asociaciones generales de fruta y variedad no implican automáticamente que se ofrece esa fruta en todas las campañas.')
V('Detalle de proveedor','Administrador > Gestión de Proveedores > Proveedor > Detalle','Documento, contacto, código de lugar de producción, sanidad, documento de identidad y frutas/variedades asociadas.','proveedores personas proveedor_frutas proveedor_variedades', 'El documento personal se guarda en personas y su archivo de identidad se referencia en archivos. Los datos de sanidad del padrón son un resumen general, no sustituyen el historial de exámenes por campaña.')
V('Fincas','Administrador > Gestión de Proveedores > Proveedor > Fincas','Lista y modal con finca, código SENASA, código catastral, departamento/provincia/distrito, coordenadas, hectáreas, cultivo, variedad y edad. La pantalla distingue los datos agronómicos por campaña.','fincas', 'Una finca pertenece a un proveedor. Validar hectáreas cultivadas ≤ totales y coordenadas emparejadas. Ubigeo, dirección y código de establecimiento quedan opcionales en el padrón porque el prototipo no siempre los muestra; pasan a ser obligatorios al preparar una guía mediante su captura histórica. No inventarlos durante importación.')
V('Certificados del proveedor','Administrador > Gestión de Proveedores > Proveedor > Certificados','Certificado SENASA con fecha de revisión y documento. La pantalla aclara que son propios y separados de los certificados de campaña.','certificados_propios', 'No exigir campaña, costo, moneda o norma a un certificado propio que solo registra nombre, revisión y archivo. Separarlo evita columnas obligatorias artificiales del certificado de campaña.')
V('Gestión de transporte','Administrador > Gestión de Transporte > Transportistas','Padrón de empresas públicas e independientes privados; filtros geográficos, selección múltiple y acceso a solicitudes.','empresas_transporte', 'Se conserva el nombre empresas_transporte del DBML por continuidad, pero con tipo de transportista y documento genérico. El independiente se vincula a personas; no exigirle RUC de once dígitos. El mismo nombre comercial de cliente y transportista no prueba que sean una sola entidad.')
V('Ficha del transportista','Administrador > Gestión de Transporte > Transportista > Detalle','Documento, tipo, contacto, ubicación, MTC y accesos explícitos a vehículos/choferes.','empresas_transporte vehiculos choferes', 'La ficha agrega información de los hijos. No mantener contadores editables de vehículos o choferes. Los códigos de empresa se referencian desde el acuerdo y no se repiten como textos en cada carga.')
V('Vehículos','Administrador > Gestión de Transporte > Transportista > Vehículos','Identificador, placa, volumen, peso neto expresado en toneladas y peso bruto.','vehiculos', 'Placa única y normalizada en el servicio. El SQL almacena kg y m³: convertir las toneladas visibles al importar. La interpretación de peso neto como capacidad de carga debe confirmarse con el negocio; no usar indistintamente tara, capacidad y peso bruto. Este es un supuesto señalado del modelo.')
V('Choferes','Administrador > Gestión de Transporte > Transportista > Choferes','Listado y modal de Miguel Torres: nombre, empresa, documento, licencia, teléfono y correo. Documento y licencia aparecen Sin registrar en el demo.','choferes personas usuarios', 'Conductor y cuenta deben referir a la misma persona. El modelo objetivo exige documento en personas y licencia en choferes; por ello el demo no se importa sin completar esos datos. No usar valores ficticios como DNI 00000000 para hacer pasar restricciones.')
V('Requerimientos y cotizaciones','Administrador > Gestión de Transporte > Requerimientos y cotizaciones','Lista con referencia, campaña, fecha, invitados, respuestas y estado; actualmente sin solicitudes guardadas.','solicitudes_transporte invitaciones_transporte cotizaciones_transporte', 'Solicitud 1:N invitados; cada invitación puede recibir N versiones de cotización. La tabla cotizaciones_transporte y sus atributos de respuesta son propuestos porque no había respuestas para inspeccionar. No afirmar que existe envío real: la interfaz lo declara simulado.')
V('Solicitar cotización','Administrador > Gestión de Transporte > Requerimientos y cotizaciones > Solicitud','Formulario abierto tras seleccionar un transportista: campaña, referencia, origen/destino, ventana del servicio, kilos/volumen estimado, vehículo, condiciones, límite, mensaje y adjunto; acción Revisar solicitud.','solicitudes_transporte invitaciones_transporte', 'La referencia es única y los invitados son una tabla puente; no serializar la lista de empresas en una columna. La cantidad estimada observada es un campo textual que puede expresar kg o volumen; se conserva como tal hasta acordar un formato estructurado. No se envió la solicitud.')
V('Cosecha y control de calidad','Administrador > Cosecha y Control de Calidad > Campañas','Pestañas Exportador e Industria, campaña y estado; en Exportador opciones Análisis y revisión, Carga y Guías; en Industria Carga y Guías.','campanias cosechas contratos_venta', 'Exportador/Industria son canales de la operación/contrato, no dos bases independientes. El listado usa campañas existentes; Agregar campaña no justifica duplicar la entidad campanias.')
V('Resumen de cosecha y calidad','Administrador > Cosecha y Control de Calidad > Campaña > Resumen','Campaña con fecha de inicio/fin y estado. El texto aclara que la calidad corresponde a cada carga.','campanias cosechas cargas', 'El estado de campaña, el de cosecha, el de calidad y el del chofer tienen responsabilidades distintas. No usar una única columna estado para cuatro procesos.')
V('Análisis y revisión','Administrador > Cosecha y Control de Calidad > Exportador > Campaña > Análisis y revisión','Muestreos por proveedor y finca, fecha, tipo, resultado, archivo y Completar/editar; residuos de plaguicidas y materia seca, con resultados pendientes y numéricos. El detalle operativo muestra MTD por finca, límite y captura/historial.','cosechas analisis_calidad mediciones_mtd', 'El análisis pertenece a una operación y finca; el MTD es historial por finca/campaña. Conservar resultado textual y numérico con unidad. No reemplazar el historial por el último valor del JSON de la finca. No se infiere un umbral reglamentario: limite_aplicado es configurable y se conserva por medición.')
V('Cargas por entrega','Administrador > Cosecha y Control de Calidad > Campaña > Cargas por entrega','Transportista, placa/chofer, entrega/cliente, kg registrados, inversión, calidad, ver/editar. La pantalla declara que la entrega se registra una sola vez, aunque los datos demo repiten en1.','cargas proveedores_carga origenes_carga gastos_carga', 'Se adopta la regla explícita de una carga por coordinación/entrega. La repetición observada se trata como anomalía del demo; no se usa para permitir duplicación silenciosa. Si se requieren viajes parciales, separar viajes y repartir kg por viaje antes de quitar esta unicidad. La carga real se detalla por proveedor/variedad; el reparto por finca no está medido en el formulario, por lo que kilos_origen puede ser nulo.')
V('Detalle de operación y carga','Administrador > Cosecha y Control de Calidad > Cargas por entrega > Detalle','Código de operación, fecha prevista, estimados, cosechado/aceptado/cargado/recibido, fincas, contrato, viaje y calidad; tabla e historial MTD con evidencia.','cosechas cargas analisis_calidad mediciones_mtd coordinaciones_entrega', 'La cantidad prevista no se sobrescribe con la real. Una operación puede abarcar varias fincas a través de la entrega; el modelo no obliga a dividir artificialmente los kilos reales por finca. Una eventual relación operación–lote físico adicional debe definirse si el negocio maneja varios lotes identificables dentro de la misma operación.')
V('Guías de remisión','Administrador > Cosecha y Control de Calidad > Campaña > Guías de remisión','Cargas con transportista, cliente, placa/chofer, peso real y guías generadas o por preparar.','guias_remision proveedores_guia normas_guia', 'Una carga admite varias guías. Cada guía distribuye cantidades de los detalles de proveedor de esa misma carga. El SQL impide consumir más kilos que los cargados y exige trazabilidad al punto de partida seleccionado. Número único generado por servicio/secuencia documental; identity es solo la clave interna.')
V('Preparar guía de remisión','Administrador > Cosecha y Control de Calidad > Guías de remisión > Carga > Preparar guía','Formulario inspeccionado con proveedores seleccionados, fecha de traslado y entrega al transportista, peso KGM, bultos, secciones de transportista, conductor, partida, llegada, normas y observaciones.','guias_remision proveedores_guia normas_guia archivos', 'Los datos de traslado son capturas históricas: cambiar la placa o dirección del padrón no debe reescribir una guía emitida. Una guía tiene un punto de partida; una cadena con varias fincas no es una dirección válida. Para distintos puntos físicos se deben preparar guías separadas y asignar kilos medidos; el backend debe comprobar totales de cabecera, bultos y distribución completa antes de emitir.')
V('Logística y despacho','Administrador > Logística y Despacho > Campañas','Totales por campaña y estado En carga, Salida de finca, En camino, Llegada, Cierre-Completado.','campanias coordinaciones_entrega cargas historial_chofer', 'El tablero se deriva de los eventos del chofer y las cargas existentes. No persistir otra copia de los contadores. Una asignación puede ser visible antes de tener carga real, por eso historial_chofer se vincula a coordinación y admite carga aún nula.')
V('Cargas de campaña','Administrador > Logística y Despacho > Campaña > Cargas','Códigos de carga, cliente/destino, camión/chofer, kilos, estado y último reporte.','cargas coordinaciones_entrega historial_chofer', 'El último reporte se obtiene por fecha/hora e id. Las diferencias de etiquetas entre tablero y ficha observadas son inconsistencias del demo; el SQL propone una sola fuente del estado: v_estado_despacho.')
V('Consulta de entrega','Administrador > Logística y Despacho > Campaña > Cargas > Entrega','Historial del chofer, viaje, datos reales de carga, proveedor/variedad, bultos, gastos, checklist, peso origen/planta, descarte y documentos. Algunas recepciones están sin peso ni respaldo pese a existir documentos financieros.','historial_chofer recepciones_planta gastos_carga', 'Una recepción física por carga. Diferencia de peso origen/planta no equivale a descarte. Porcentaje de descarte=descarte/origen×100; no guardarlo además como dato editable. El reporte de recepción y el resultado son necesarios para preparar una factura. Para importar históricos incompletos se necesita una migración excepcional controlada: el SQL nuevo no inventa los pesos ausentes.')
V('Facturación y cobros — Campañas','Administrador > Facturación y cobros > Campañas','Campañas con cargas, incluidas finalizadas; ingreso a clientes.','campanias cargas', 'Es una consulta, sin nueva tabla financiera por campaña. Acceso a campaña cerrada debe ser de consulta.')
V('Clientes de campaña','Administrador > Facturación y cobros > Campaña > Clientes','Cliente, RUC, cargas, kilos contratados, número de contratos, total contratado y resumen facturado/cobrado/saldo.','clientes contratos_venta facturas_venta cobros_venta', 'Separar contratado, preparado y facturado. Sumar por moneda del documento; la UI muestra totales USD, pero hay contratos PEN en la misma campaña. Un resumen único mezclado sería incorrecto.')
V('Cargas registradas del cliente','Administrador > Facturación y cobros > Campaña > Cliente > Cargas','Acordeones por carga, kg cargados/recibidos/facturados, precio, reporte de recepción y estado de factura; acciones preparar/consultar factura, registrar cobro e historial. En DEMO-FACTURAR-001 se observaron 580 kg cargados y 570 facturados.','facturas_venta', 'Conservar kg facturados, precio aplicado, moneda e importe histórico. El SQL toma como base el peso recibido, según lo mostrado. No volver a calcular documentos emitidos desde el peso o precio actual. Una preparación es estado PREPARADA; solo pasa a EMITIDA al registrar número, fecha y archivo de la factura externa. No implica emisión fiscal electrónica desde esta app.')
V('Historial de cobros','Administrador > Facturación y cobros > Cliente > Factura > Cobros','Fecha, monto, medio, referencia y evidencia; total, cobrado y saldo. Se observó un cobro parcial de USD 500 frente a USD 1,368.','cobros_venta', 'Factura 1:N cobros. La moneda proviene de la factura. Las referencias son únicas por documento; el SQL evita sobrecobro y prohíbe editar o borrar movimientos. Falta diseñar un flujo explícito de reversos si se requieren correcciones.')
